local _b64 = table.concat(_payload)
local _alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _map = {}
for _i = 1, #_alphabet do _map[string.byte(_alphabet, _i)] = _i - 1 end
local _codes = {}
local _buffer, _bits, _byteIndex = 0, 0, 0
local _high = nil
for _i = 1, #_b64 do
    local _v = _map[string.byte(_b64, _i)]
    if _v then
        _buffer = _buffer * 64 + _v
        _bits = _bits + 6
        if _bits >= 8 then
            _bits = _bits - 8
            local _byte = math.floor(_buffer / (2 ^ _bits)) % 256
            _buffer = _buffer % (2 ^ _bits)
            _byteIndex = _byteIndex + 1
            _byte = bit32.bxor(_byte, (_byteIndex * 43 + 17) % 256)
            if _high == nil then
                _high = _byte
            else
                _codes[#_codes + 1] = _high * 256 + _byte
                _high = nil
            end
        end
    end
end
